import { after } from 'next/server';
import { headers } from 'next/headers';
import { logPageView } from '@/lib/analytics';

export default async function Home() {
  // Schedule analytics logging after the response is sent
  // This uses Next.js's after() API to ensure logging doesn't block the response
  after(async () => {
    const headersList = await headers();
    const userAgent = headersList.get('user-agent') || undefined;

    await logPageView({
      path: '/',
      timestamp: new Date().toISOString(),
      userAgent,
    });
  });

  return (
    <main>
      <h1>Welcome to Our Application!</h1>
      <p>
        This page logs analytics data without blocking the response. The
        logging happens after the page is sent to your browser.
      </p>
    </main>
  );
}

